with unpacked as (select id, customer_id, created_at, items, ship_to, attributes, array_join(array_sort(coupon_codes), ',') as coupons_text, size(items) as num_items, size(filter(items, x -> x.qty >= 3)) as bulk_lines from carts) select customer_id, count(*) as event_count, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as duration_min, min(created_at) as first_created_at, round(avg(num_items), 2) as avg_num_items, round(avg(bulk_lines), 2) as avg_bulk_lines, min(created_at) as first_created_at_2 from unpacked group by customer_id order by avg_num_items desc nulls last;
